/**
 * Reset the physics store, disposing the debug material and clearing listeners.
 * Call this on Physics.dispose() to prevent memory leaks across HMR reloads.
 */
export function resetPhysicStore(): void;
/**
 * Default turn capacity (radians per second).
 * @type {number}
 */
export const defaultTurnCapacity: number;
/**
 * Default force capacity (units per second squared).
 * @type {number}
 */
export const defaultForceCapacity: number;
/**
 * Default capsule collider radius.
 * @type {number}
 */
export const capsuleRadius: number;
/**
 * Default capsule collider height (segment length).
 * @type {number}
 */
export const capsuleLength: number;
export const getPhysic: any;
export const setPhysic: any;
export const subscribePhysicStore: any;
